async function showStock(url) {
  const status = document.getElementById("status");
  const list = document.getElementById("stock");
  status.textContent = "Loading...";          // shown straight away
  list.innerHTML = "";
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const items = await response.json();      // throws on broken JSON
    for (const item of items) {
      const li = document.createElement("li");
      li.textContent = `${item.name}: ${item.qty}`;
      list.appendChild(li);
    }
    status.textContent = `${items.length} items`;
    return true;
  } catch (err) {
    status.textContent = "Could not load stock. Try again.";
    return false;
  }
}

async function lowStock(url, threshold) {
  try {
    const response = await fetch(url);
    if (!response.ok) return null;
    const items = await response.json();
    return items
      .filter((item) => item.qty < threshold)
      .map((item) => item.name)
      .sort((a, b) => a.localeCompare(b));
  } catch (err) {
    return null;     // broken JSON (or anything else unexpected)
  }
}
